definition.script:
pipeline {
    agent any
    stages {
        stage('Checkout') {
            steps {
                sh 'git config --global http.sslVerify false'
                git branch: 'master', url: 'https://admin:admin@gitblit:8443/r/node_test.git'
            }
        }
        stage('Install') {
            steps {
                sh 'npm install || echo "No dependencies found"'
            }
        }
        stage('Package') {
            steps {
                sh '''
                ARTIFACT_DIR="/var/jenkins_home/artifacts"
                mkdir -p $ARTIFACT_DIR
                tar -czvf $ARTIFACT_DIR/node_app.tar.gz .
                echo "Artifact saved to $ARTIFACT_DIR/node_app.tar.gz"
                '''
            }
        }
    }
}
